'use strict';
function createMischief({audio,canvas,ctx,cut,toast,burst,nextMode,setMode,getAudioContext}){
 const el=id=>document.getElementById(id),faceButton=el('face-button');
 let pose={x:0,y:0,size:200,rot:0,sx:1,sy:1},drag=null,pull={x:0,y:0},reaction=0,hat=0,shades=false,moustache=false,event=null,decals=[],shots=[],copies=[],incidents=0;
 const hats=['','top-hat','tomato','fried-egg','ufo','egg'],palette=['#ff00bb','#00bfff','#ffe600','#7027ff','#3ad441'];
 const pixel=document.createElement('canvas');pixel.width=28;pixel.height=44;const pc=pixel.getContext('2d');
 const gentle=()=>el('gentle').checked,now=()=>performance.now()/1000;
 function report(text){el('toy-status').textContent=text;el('crime-count').textContent=++incidents+' incident'+(incidents===1?'':'s')}
 function noise(kind){if(window.JustinLive?.muted())return;if(!el('sfx').checked)return;const ac=getAudioContext();if(!ac||ac.state!=='running')return;const o=ac.createOscillator(),gain=ac.createGain(),start=ac.currentTime;o.type=kind==='egg'?'triangle':'sine';o.frequency.setValueAtTime(kind==='boop'?700:kind==='ufo'?110:300,start);o.frequency.exponentialRampToValueAtTime(kind==='ufo'?900:70,start+.18);gain.gain.setValueAtTime(.055*audio.volume,start);gain.gain.exponentialRampToValueAtTime(.001,start+.25);o.connect(gain);gain.connect(ac.destination);o.start();o.stop(start+.26)}
 function localPoint(x,y){const dx=x-pose.x,dy=y-pose.y,c=Math.cos(-pose.rot),s=Math.sin(-pose.rot);return {x:Math.max(-.45,Math.min(.45,(dx*c-dy*s)/(pose.size*pose.sx))),y:Math.max(-.6,Math.min(.6,(dx*s+dy*c)/(pose.size*pose.sy)))}}
 function mark(kind,x,y){decals.push({kind,...localPoint(x,y),color:palette[Math.floor(Math.random()*palette.length)],angle:Math.random()});if(decals.length>24)decals.shift()}
 function hit(kind,x,y){reaction=1;noise(kind);if(kind==='tomato'||kind==='egg'){mark(kind,x,y);report(kind==='egg'?'omelette du justin':'fresh produce has arrived')}else if(kind==='paint'){mark(kind,x,y);report('a fine arts degree was not involved')}else{burst(x,y,10);report('nose booped. factory settings restored?')}}
 function act(x=pose.x,y=pose.y){const tool=el('tool').value;if(tool==='dance'){nextMode();return}if(tool==='paint'||tool==='boop'){hit(tool,x,y);return}if(gentle()){hit(tool,x,y);return}const rect=canvas.getBoundingClientRect();shots.push({kind:tool,start:now(),x:Math.random()>.5?rect.width+40:-40,y:rect.height*.2,tx:x,ty:y});if(shots.length>12)shots.shift()}
 function point(e){const r=canvas.getBoundingClientRect();return {x:e.clientX-r.left,y:e.clientY-r.top}}
 for(const target of [faceButton,canvas]){target.style.touchAction='none';target.addEventListener('pointerdown',e=>{if(e.button!==0)return;const p=point(e);drag={id:e.pointerId,start:p,last:p,target,moved:false};target.setPointerCapture(e.pointerId)});target.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;const p=point(e);drag.last=p;const dx=p.x-drag.start.x,dy=p.y-drag.start.y;if(Math.hypot(dx,dy)>8)drag.moved=true;if(drag.moved){pull.x=Math.max(-260,Math.min(260,dx));pull.y=Math.max(-220,Math.min(220,dy));el('toy-status').textContent='stop pulling him he has places to be'}});target.addEventListener('pointerup',e=>{if(!drag||drag.id!==e.pointerId)return;const p=point(e),moved=drag.moved;drag=null;if(moved){reaction=1;noise('boop');report('elasticity test: concerning')}else act(p.x,p.y)});target.addEventListener('pointercancel',()=>{drag=null});target.addEventListener('lostpointercapture',()=>{drag=null})}
 faceButton.onclick=e=>{if(e.detail===0)act()};canvas.onclick=null;
 el('hat').onclick=()=>{hat=(hat+1)%hats.length;report(hat?'he has been promoted to '+hats[hat]:'hat privileges revoked')};
 el('glasses').onclick=()=>{shades=!shades;el('glasses').setAttribute('aria-pressed',String(shades));report(shades?'unemployed but mysterious':'he can see again')};
 el('moustache').onclick=()=>{moustache=!moustache;el('moustache').setAttribute('aria-pressed',String(moustache));report(moustache?'this is obviously a different person':'disguise removed')};
 function special(type){event={type,start:now(),duration:type==='abduct'?5:3.5};noise(type==='abduct'?'ufo':'boop');report(type==='abduct'?'the aliens requested a refund': 'do not overfill the justin')}
 el('abduct').onclick=()=>special('abduct');el('inflate').onclick=()=>special('inflate');
 el('print').onclick=()=>{for(let i=0;i<8;i++)copies.push({x:pose.x,y:pose.y,vx:(Math.random()-.5)*240,vy:-90-Math.random()*220,angle:Math.random()*2,life:5+Math.random()*2});if(copies.length>12)copies.splice(0,copies.length-12);noise('boop');report('printer error: too much justin')};
 el('mystery').onclick=()=>{hat=1+Math.floor(Math.random()*(hats.length-1));shades=Math.random()>.4;moustache=Math.random()>.5;el('glasses').setAttribute('aria-pressed',String(shades));el('moustache').setAttribute('aria-pressed',String(moustache));el('quality').value=['normal','fried','pixel','negative'][Math.floor(Math.random()*4)];setMode(Math.floor(Math.random()*12));[el('print'),el('abduct'),el('inflate')][Math.floor(Math.random()*3)].click();report('we let the computer decide. unfortunate.')};
 el('speed').oninput=e=>{audio.playbackRate=Number(e.target.value)/100;audio.preservesPitch=false;audio.webkitPreservesPitch=false;el('speed-out').textContent=audio.playbackRate>1.1?'chipmunk guy':audio.playbackRate<.9?'sleepy guy':'normal guy'};
 el('undo').onclick=()=>{hat=0;shades=moustache=false;event=null;decals=[];shots=[];copies=[];reaction=0;pull={x:0,y:0};drag=null;el('glasses').setAttribute('aria-pressed','false');el('moustache').setAttribute('aria-pressed','false');el('quality').value='normal';el('speed').value=100;audio.playbackRate=1;audio.preservesPitch=true;audio.webkitPreservesPitch=true;el('speed-out').textContent='normal guy';el('tool').value='dance';setMode(0);report('justin has been pressure washed')};
 function apply(p,dt,t){const factor=gentle()?.15:1;reaction*=Math.exp(-dt*9);if(!drag){pull.x*=Math.exp(-dt*10);pull.y*=Math.exp(-dt*10)}p.x+=pull.x*.35*factor;p.y+=pull.y*.3*factor;p.sx*=1+Math.abs(pull.x)/250*factor+reaction*.2*factor;p.sy*=1+Math.abs(pull.y)/220*factor-reaction*.16*factor;p.rot+=pull.x/900*factor;
 if(event){const age=t-event.start;if(age>event.duration)event=null;else if(event.type==='abduct'){const lift=age<1?0:age<3?Math.min(1,(age-1)/1.2):Math.max(0,(5-age)/2);p.y-=lift*canvas.getBoundingClientRect().height*.8*factor;p.sx*=1-lift*.65*factor;p.sy*=1-lift*.65*factor;p.rot+=Math.sin(age*9)*.08*factor}else{const swell=Math.sin(Math.min(1,age/event.duration)*Math.PI);p.sx*=1+swell*.75*factor;p.sy*=1+swell*.25*factor;p.y-=swell*35*factor}}
 pose={...p};return p}
 function image(){if(el('quality').value==='pixel'){pc.clearRect(0,0,28,44);pc.drawImage(cut,0,0,28,44);return pixel}return window.JustinSprites?JustinSprites.animated(window.justinClicker?.skin):cut}
 function filter(){const manual=el('quality').value==='fried'?'saturate(5) contrast(2.3) sepia(.3)':el('quality').value==='negative'?'invert(1) hue-rotate(90deg)':'none',skin=window.JustinSprites?'none':window.justinClicker?.skin.filter||'none';return [manual,skin].filter(x=>x!=='none').join(' ')||'none'}
 function dress(size){const ht=size*1280/820;ctx.save();ctx.filter='none';ctx.imageSmoothingEnabled=true;if(hat)drawProp(ctx,hats[hat],0,-ht*.4,size*(hats[hat]==='ufo'?1.25:.8));if(shades||window.justinClicker?.skin.id==='cool')drawProp(ctx,'sunglasses',0,-size*.09,size*.93);if(moustache)drawProp(ctx,'moustache',0,size*.28,size*.55);for(const d of decals){ctx.save();ctx.translate(d.x*size,d.y*size);ctx.rotate(d.angle);if(d.kind==='egg')drawProp(ctx,'fried-egg',0,0,size*.32);else{ctx.fillStyle=d.kind==='tomato'?'#ed251ce0':d.color;for(let i=0;i<7;i++){ctx.beginPath();ctx.arc(Math.cos(i*2.4)*size*.045,Math.sin(i*2.4)*size*.045,size*(i===0?.065:.025),0,Math.PI*2);ctx.fill()}ctx.fillRect(-size*.014,0,size*.025,size*.15)}ctx.restore()}ctx.restore()}
 function behind(t,w,h){if(!event||event.type!=='abduct')return;const age=t-event.start,fade=Math.min(1,age*2,(5-age)*2);ctx.save();ctx.globalAlpha=Math.max(0,fade)*.16;ctx.fillStyle='#90ff3b';ctx.beginPath();ctx.moveTo(w/2,45);ctx.lineTo(w/2-130,h);ctx.lineTo(w/2+130,h);ctx.closePath();ctx.fill();ctx.globalAlpha=Math.max(0,fade);drawProp(ctx,'ufo',w/2,55,145);ctx.restore()}
 function front(t,dt,w,h,draw){ctx.save();for(const shot of shots){const p=Math.min(1,(t-shot.start)/.4),e=1-(1-p)*(1-p);ctx.save();ctx.translate(shot.x+(shot.tx-shot.x)*e,shot.y+(shot.ty-shot.y)*e-Math.sin(p*Math.PI)*90);ctx.rotate(p*7);drawProp(ctx,shot.kind==='egg'?'egg':'tomato',0,0,45);ctx.restore();if(p===1&&!shot.done){shot.done=true;hit(shot.kind,shot.tx,shot.ty)}}shots=shots.filter(s=>!s.done);for(const copy of copies){copy.life-=dt;const motion=dt*(gentle()?.12:1);copy.x+=copy.vx*motion;copy.y+=copy.vy*motion;copy.vy+=100*motion;if(copy.y>h-35&&copy.vy>0){copy.y=h-35;copy.vy*=-.65}copy.angle+=dt;draw(copy.x,copy.y,pose.size*.22,copy.angle,1,1,Math.min(1,copy.life))}copies=copies.filter(c=>c.life>0);ctx.restore()}
 function snapshot(){return {hat,shades,moustache,quality:el('quality').value}}
 function restore(data){hat=Math.max(0,Math.min(hats.length-1,Math.floor(data.hat)||0));shades=Boolean(data.shades);moustache=Boolean(data.moustache);el('glasses').setAttribute('aria-pressed',String(shades));el('moustache').setAttribute('aria-pressed',String(moustache));el('quality').value=['normal','fried','pixel','negative'].includes(data.quality)?data.quality:'normal';decals=[];shots=[];copies=[];event=null;reaction=0}
 return {apply,image,filter,dress,behind,front,snapshot,restore};
}
